INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32011, 'Mark 7:15', 'Mark', 7, 15, 'هېڅ داسې شی نشته چې انسان یې وخوري او ورباندې ناپاکه شي، خو کومې بدې خبرې چې د انسان د زړه څخه راوځي هغه انسان ناپاکه کوي. [', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_15.mp3', '', 1761754199, 1761754199),
(32012, 'Mark 7:16', 'Mark', 7, 16, 'که څوک غوږونه لري، نو هغه دې واوري.]»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_16.mp3', '', 1761754199, 1761754199),
(32013, 'Mark 7:17', 'Mark', 7, 17, 'کله چې عیسی د خلکو څخه رخصت شو او کور ته ننوت، نو شاګردانو یې د دې مثال په هکله د هغه څخه پوښتنه وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_17.mp3', '', 1761754199, 1761754199),
(32014, 'Mark 7:18', 'Mark', 7, 18, 'عیسی هغوی ته وویل: «ایا تاسو هم د نورو په شان ناپوهه یئ؟ ایا نه پوهېږئ چې کوم شی چې له بهر نه د انسان وجود ته ننوځي، نه شي کولای هغه ناپاکه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_18.mp3', '', 1761754199, 1761754199),
(32015, 'Mark 7:19', 'Mark', 7, 19, 'ځکه چې دا خواړه د هغه زړه ته نه ننوځي بلکې د هغه خېټې ته ځي او وروسته بیا د بدن څخه وځي.» په دې خبرې عیسی ټول خواړه حلال اعلان کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_19.mp3', '', 1761754199, 1761754199),
(32016, 'Mark 7:20', 'Mark', 7, 20, 'او هغه زیاته کړه: «څه چې د انسان له دننه راوځي هغه ورباندې ناپاکه کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_20.mp3', '', 1761754199, 1761754199),
(32017, 'Mark 7:21', 'Mark', 7, 21, 'ځکه چې د انسان د زړه څخه بد خیالونه، جنسي بد‌اخلاقي، غلا، قتل،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_21.mp3', '', 1761754199, 1761754199),
(32018, 'Mark 7:22', 'Mark', 7, 22, 'زناکاري، حرص، بدي، ټګي، شهوت‌پرستي، بخیلي، تور لګول، غرور او بې‌عقلي راوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_22.mp3', '', 1761754199, 1761754199),
(32019, 'Mark 7:23', 'Mark', 7, 23, 'دا ټول بد شیان له دننه څخه راوځي او انسان ناپاکه کوي.» د یوې غیریهودۍ ښځې ایمان (متي ۱۵‏:‌۲۱‌‏-‌۲۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_23.mp3', '', 1761754199, 1761754199),
(32020, 'Mark 7:24', 'Mark', 7, 24, 'بیا عیسی له هغه ځای څخه روان شو او د صور سیمې ته لاړ. هغه یو کور ته ورغی او نه یې غوښتل چې څوک ورباندې پوه شي چې هغه هلته دی، خو ویې نه شو کولای چې پټ پاتې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_24.mp3', '', 1761754199, 1761754199),
(32021, 'Mark 7:25', 'Mark', 7, 25, 'سمدلاسه یوه ښځه چې لور یې پېریانو نیولې وه د عیسی نه خبره شوه او راغله او د هغه په پښو کې پرېوتله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_25.mp3', '', 1761754199, 1761754199),
(32022, 'Mark 7:26', 'Mark', 7, 26, 'هغه ښځه یونانۍ وه او د سوریې د فینیقیې په سیمه کې زېږېدلې وه. هغې عیسی ته زاري وکړه چې د لور څخه یې پېریان وباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_26.mp3', '', 1761754199, 1761754199),
(32023, 'Mark 7:27', 'Mark', 7, 27, 'خو عیسی هغې ته وویل: «پرېږده چې لومړی ماشومان ماړه شي، دا سمه نه ده چې څوک دې د ماشوم ډوډۍ واخلي او سپیانو ته یې واچوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_27.mp3', '', 1761754199, 1761754199),
(32024, 'Mark 7:28', 'Mark', 7, 28, 'هغې ځواب ورکړ: «هو، ښاغلیه! خو د کور سپي هم د ماشومانو د ډوډۍ پاتې شونې خوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_28.mp3', '', 1761754199, 1761754199),
(32025, 'Mark 7:29', 'Mark', 7, 29, 'بیا عیسی هغې ته وویل: «دا چې ښه ځواب دې ووایه نو خپل کور ته لاړه شه، ستا د لور څخه پېریان وتلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_29.mp3', '', 1761754199, 1761754199),
(32026, 'Mark 7:30', 'Mark', 7, 30, 'کله چې هغه ښځه بېرته کور ته لاړه، نو ویې لیدل چې لور یې په کټ کې پرته وه او پېریان ترې وتلي وو. عیسی یو کوڼ سړي ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_30.mp3', '', 1761754199, 1761754199),
(32027, 'Mark 7:31', 'Mark', 7, 31, 'بیا عیسی د صور له سیمې څخه راستون شو او د صیدون او دکاپولس په لاره د جلیل بحیرې ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_31.mp3', '', 1761754199, 1761754199),
(32028, 'Mark 7:32', 'Mark', 7, 32, 'په هغه ځای کې ځینو خلکو هغه ته یو سړی چې کوڼ ؤ او ژبه یې هم بندېدله، راوست. هغوی ورته زاري وکړه چې په هغه سړي باندې خپل لاس کېږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_32.mp3', '', 1761754199, 1761754199),
(32029, 'Mark 7:33', 'Mark', 7, 33, 'نو عیسی هغه سړی د خلکو د ګڼې‌ګوڼې څخه یوې خواته بوته او خپلې ګوتې یې د هغه په غوږونو کې کېښودلې، بیا یې ګوتې په لاړو لمدې کړې او ژبه یې ورته لمس کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_33.mp3', '', 1761754199, 1761754199),
(32030, 'Mark 7:34', 'Mark', 7, 34, 'بیا عیسی اسمان ته وکتل، اوسېلی یې وویست او هغه ته یې وویل: «افتح» چې معنی یې ده «خلاص شئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_34.mp3', '', 1761754199, 1761754199),
(32031, 'Mark 7:35', 'Mark', 7, 35, 'سمدلاسه د هغه سړي غوږونه خلاص شول، د ژبې بندېدل یې ښه شول او په عادي توګه یې خبرې کول پیل کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_35.mp3', '', 1761754199, 1761754199),
(32032, 'Mark 7:36', 'Mark', 7, 36, 'عیسی هغوی ته امر وکړ چې په دې هکله هېچا ته څه ونه وایي، خو هرڅومره چې عیسی هغوی د دې کار څخه منع کول، همدومره به هغوی دا خبره نوره هم خپروله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_36.mp3', '', 1761754199, 1761754199),
(32033, 'Mark 7:37', 'Mark', 7, 37, 'خلک ډېر زیات حیران شوي وو او ویل یې: «د هغه ټول کارونه حیرانوونکي دي. حتی هغه کاڼه روغ کړل چې واوري او ګونګیان یې روغ کړل چې خبرې وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_37.mp3', '', 1761754199, 1761754199),
(32034, 'Mark 16:1', 'Mark', 16, 1, 'کله چې د سبت ورځ تېره شوه، مریم مجدلیې او د یعقوب مور مریم او سالومې خوشبویه تېل واخیستل او لاړلې چې د عیسی په مړي باندې یې واچوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_1.mp3', '', 1761754199, 1761754199),
(32035, 'Mark 16:2', 'Mark', 16, 2, 'د یکشنبې په ورځ سهار د لمر راختلو نه وروسته هغوی قبر ته ورغلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_2.mp3', '', 1761754199, 1761754199),
(32036, 'Mark 16:3', 'Mark', 16, 3, 'هغوی په خپلو کې یو بل ته وویل: «مونږ ته به د قبر د خولې څخه تیږه څوک ورغړوي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_3.mp3', '', 1761754199, 1761754199),
(32037, 'Mark 16:4', 'Mark', 16, 4, 'خو کله چې هغوی وکتل، نو ویې لیدل چې هغه تیږه چې ډېره غټه وه شاته رغړېدلې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_4.mp3', '', 1761754199, 1761754199),
(32038, 'Mark 16:5', 'Mark', 16, 5, 'کله چې هغوی قبر ته ورننوتلې، نو هلته یې یو ځوان سړی ولیده چې سپین کالي یې اغوستي وو او د قبر ښي خواته ناست ؤ. نو هغوی ووېرېدلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_5.mp3', '', 1761754199, 1761754199),
(32039, 'Mark 16:6', 'Mark', 16, 6, 'خو هغه وویل: «مه وېرېږئ، زه پوهېږم چې تاسو ناصري عیسی لټوئ چې په صلیب باندې ځوړند شوی ؤ. هغه دلته نشته، هغه راژوندی شوی دی. ګورئ، دا هغه ځای دی چې د هغه مړی په کې ایښودل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_6.mp3', '', 1761754199, 1761754199),
(32040, 'Mark 16:7', 'Mark', 16, 7, 'اوس لاړې شئ او د هغه شاګردانو او پطروس ته ووایئ چې هغه ستاسو څخه مخکې جلیل ته روان دی. لکه څنګه چې هغه خپله تاسو ته ویلي وو، تاسو به هغه هلته ووینئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_7.mp3', '', 1761754199, 1761754199),
(32041, 'Mark 16:8', 'Mark', 16, 8, 'هغوی د قبر څخه راووتلې او وتښتېدلې، ځکه چې د ډېرې وېرې لړزېدلې او وارخطا شوې وې. هغوی هېچا ته څه ونه ویل، ځکه چې وېرېدلې وې. عیسی مریم مجدلیې ته ښکاره کیږي (متي ۲۸‏:‌۹‌‏-‌۱۰ او یوحنا ۲۰‏:‌۱۱‌‏-‌۱۸) [', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_8.mp3', '', 1761754199, 1761754199),
(32042, 'Mark 16:9', 'Mark', 16, 9, 'کله چې عیسی د یکشنبې په ورځ سهار وختي د مړو نه راژوندی شو، نو لومړی مریم مجدلیې ته چې هغه ورڅخه اووه پېریان ویستلي وو ښکاره شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_9.mp3', '', 1761754199, 1761754199),
(32043, 'Mark 16:10', 'Mark', 16, 10, 'هغه لاړه او څه چې پېښ شوي وو هغه یې د عیسی نژدې ملګرو ته چې ویر او ژړاګانې یې کولې، وویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_10.mp3', '', 1761754199, 1761754199),
(32044, 'Mark 16:11', 'Mark', 16, 11, 'کله چې هغوی واورېدل چې عیسی ژوندی شوی دی او مریم لیدلی دی، نو باور یې ورباندې ونه کړ. عیسی دوو شاګردانو ته ښکاره کیږي (لوقا ۲۴‏:‌۱۳‌‏-‌۳۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_11.mp3', '', 1761754199, 1761754199),
(32045, 'Mark 16:12', 'Mark', 16, 12, 'له هغې وروسته عیسی په بله څېره کې خپلو دوو شاګردانو ته چې د اورشلیم څخه کلي ته روان وو، ښکاره شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_12.mp3', '', 1761754199, 1761754199),
(32046, 'Mark 16:13', 'Mark', 16, 13, 'هغوی بېرته لاړل او نور شاګردان یې خبر کړل، خو هغوی یې په خبره باندې باور ونه کړ. عیسی خپلو یوولسو شاګردانو ته ښکاره کیږي (متي ۲۸‏:‌۱۶‌‏-‌۲۰ او لوقا ۲۴‏:‌۳۶‌‏-‌۴۹ او یوحنا ۲۰‏:‌۱۹‌‏-‌۲۳ او د رسولانو عملونه ۱‏:‌۶‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_13.mp3', '', 1761754199, 1761754199),
(32047, 'Mark 16:14', 'Mark', 16, 14, 'وروسته بیا عیسی خپل ځان یوولسو شاګردانو ته چې ډوډۍ ته ناست وو، ورښکاره کړ. هغوی یې د بې‌ایمانۍ او سختو زړونو د لرلو په خاطر ورټل، ځکه چې هغوی د هغو خلکو په خبرو یقین ونه کړ چې هغه یې د راژوندي کېدلو څخه وروسته لیدلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_14.mp3', '', 1761754199, 1761754199),
(32048, 'Mark 16:15', 'Mark', 16, 15, 'نو هغوی ته یې وویل: «په ټوله نړۍ کې وګرځئ او دا زېری ټولو ته ورسوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_15.mp3', '', 1761754199, 1761754199),
(32049, 'Mark 16:16', 'Mark', 16, 16, 'هرڅوک چې ایمان راوړي او د تعمید غسل واخلي نو هغه به خلاصون ومومي، خو څوک چې ایمان رانه وړي نو هغه به محکوم کړای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_16.mp3', '', 1761754199, 1761754199),
(32050, 'Mark 16:17', 'Mark', 16, 17, 'څوک چې ایمان راوړي، نو هغوی ته به دا نښه ورکړل شي چې زما په نوم به پېریان وباسي او په نویو ژبو به خبرې کوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_17.mp3', '', 1761754199, 1761754199),
(32051, 'Mark 16:18', 'Mark', 16, 18, 'هغوی به ماران نیسي او که زهر وخوري، نو زیان به ورته نه رسیږي او کله چې په ناروغانو باندې خپل لاسونه ږدي، نو هغوی به ښه کیږي.» اسمان ته د عیسی ختل (لوقا ۲۴‏:‌۵۰‌‏-‌۵۳ او د رسولانو عملونه ۱‏:‌۹‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_18.mp3', '', 1761754199, 1761754199),
(32052, 'Mark 16:19', 'Mark', 16, 19, 'د هغوی سره د خبرو کولو نه وروسته څښتن عیسی اسمان ته پورته یووړل شو او د خدای ښي لاس ته کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_19.mp3', '', 1761754199, 1761754199),
(32053, 'Mark 16:20', 'Mark', 16, 20, 'بیا شاګردان لاړل او په هرځای کې یې وعظ کاوه او څښتن ورسره مرسته کوله او د معجزو په ښودلو یې دا ثابته کړه چې د هغوی پیغام رښتینی دی.]', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark16_verse_20.mp3', '', 1761754199, 1761754199),
(32054, 'Revelation 22:1', 'Revelation', 22, 1, 'بیا فرښتې ماته د ژوندون د اوبو سیند وښوده چې د بلور په شان ځلېده او د خدای او وري د تخت څخه بهېده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_1.mp3', '', 1761754199, 1761754199),
(32055, 'Revelation 22:2', 'Revelation', 22, 2, 'او د ښار د لوی سرک له منځ نه تېرېده. د سیند په دواړو غاړو کې د ژوندانه ونه وه چې په کال کې به یې دولس ډوله مېوه نیوله او هره میاشت کې به یې یوځل. د دې ونې پاڼې د قومونو د علاج دپاره وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_2.mp3', '', 1761754199, 1761754199),
(32056, 'Revelation 22:3', 'Revelation', 22, 3, 'په هغه ښار کې به نور داسې شی نه وي چې د خدای لعنت ورباندې وي. د خدای او وري تخت به په هغه ښار کې وي او د خدای خدمتګاران به د خدای عبادت کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_3.mp3', '', 1761754199, 1761754199),
(32057, 'Revelation 22:4', 'Revelation', 22, 4, 'هغوی به هغه مخامخ ویني او د هغه نوم به د هغوی په تندیو باندې لیکل شوی وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_4.mp3', '', 1761754199, 1761754199),
(32058, 'Revelation 22:5', 'Revelation', 22, 5, 'هلته به نوره شپه نه وي او هغوی به د څراغ یا لمر رڼا ته اړتیا نه لري، ځکه څښتن خدای به د هغوی دپاره رڼا وي او هغوی به تل ترتله هلته پاچاهي کوي. د عیسی راتلل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_5.mp3', '', 1761754199, 1761754199),
(32059, 'Revelation 22:6', 'Revelation', 22, 6, 'بیا فرښتې ماته وویل: «دا خبرې د باور وړ او رښتیا دي. څښتن خدای چې خپلو پیغمبرانو ته الهام ورکوي، خپله فرښته رالېږلې ده چې خپلو خدمتګارانو ته هغه شیان وروښایي چې ډېر زر به پېښ شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_6.mp3', '', 1761754199, 1761754199),
(32060, 'Revelation 22:7', 'Revelation', 22, 7, 'عیسی مسیح وایي: «واورئ، زه زر درځم، بختور دی هغه څوک چې د دې کتاب پېشګویانې او پیغامونه مني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_7.mp3', '', 1761754199, 1761754199),
(32061, 'Revelation 22:8', 'Revelation', 22, 8, 'زه یوحنا هغه څوک یم چې دا شیان مې واورېدل او ومې لیدل. څنګه چې مې دا شیان واورېدل او ولیدل، نو د هغې فرښتې په پښو کې چې دا شیان یې راته ښودلي وو، پرېوتم چې سجده ورته وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_8.mp3', '', 1761754199, 1761754199),
(32062, 'Revelation 22:9', 'Revelation', 22, 9, 'خو هغې ماته وویل: «داسې مه کوه! زه خو ستا او ستا د ورونو یعنې پیغمبرانو او هغو کسانو په شان چې د دې کتاب پیغامونه مني، د خدای یوه خدمتګاره یم. یوازې د خدای عبادت کوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_9.mp3', '', 1761754199, 1761754199),
(32063, 'Revelation 22:10', 'Revelation', 22, 10, 'بیا هغې ماته وویل: «د دې کتاب پېشګویانې او پیغامونه مه پټوه، ځکه چې هغه وخت نژدې دی چې دا شیان به پېښ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_10.mp3', '', 1761754199, 1761754199),
(32064, 'Revelation 22:11', 'Revelation', 22, 11, 'پرېږده چې بدکاران خپل بد کارونه وکړي او فاسد خلک خپل فساد ته دوام ورکړي، عادلان دې خپلو نېکو کارونو ته دوام ورکړي او سپېڅلي خلک دې سپېڅلي اوسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_11.mp3', '', 1761754199, 1761754199),
(32065, 'Revelation 22:12', 'Revelation', 22, 12, 'عیسی وایي: «واورئ، زه زر درځم او د ځان سره به هرچا ته د هغه د عملونو سره سم اجر او بدل ورکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_12.mp3', '', 1761754199, 1761754199),
(32066, 'Revelation 22:13', 'Revelation', 22, 13, 'زه الف او یا یم، زه اول او اخر یم، زه شروع او پای یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_13.mp3', '', 1761754199, 1761754199),
(32067, 'Revelation 22:14', 'Revelation', 22, 14, 'بختور دي هغه خلک چې خپلې چپنې پاکې ووینځي، ترڅو د دې حق ولري چې د ژوندانه د ونې مېوه وخوري او وکولای شي چې ښار ته د دروازو له لارې ورننوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_14.mp3', '', 1761754199, 1761754199),
(32068, 'Revelation 22:15', 'Revelation', 22, 15, 'خو سپي، جادوګران، زناکاران، قاتلان، بت‌پرستان او دروغجن خلک به د ښار څخه دباندې پاتې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_15.mp3', '', 1761754199, 1761754199),
(32069, 'Revelation 22:16', 'Revelation', 22, 16, '«ما عیسی خپله فرښته تاسو ته درولېږله چې کلیساګانو دپاره دا پیغام ورسوي. زه د داود د نسل څخه یم او د سهار ځلېدونکی ستوری یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_16.mp3', '', 1761754199, 1761754199),
(32070, 'Revelation 22:17', 'Revelation', 22, 17, 'روح القدس او ناوې عیسی ته وایي: «راشه!» او څوک یې چې اوري، هغه دې هم ووایي: «راشه!» څوک چې تږی وي، هغه دې راشي، او څوک چې د ژوندون اوبه غواړي، هغه دې دا اوبه لاسته راوړي، ځکه چې وړیا دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_17.mp3', '', 1761754199, 1761754199),
(32071, 'Revelation 22:18', 'Revelation', 22, 18, 'زه یوحنا هر هغه چاته چې د دې کتاب پېشګویانې او پیغامونه اوري، خبرداری ورکوم چې که چېرې څوک د خپل ځان نه په هغه کې کوم شی ورزیات کړي، نو خدای به هغه بلاګانې چې په دې کتاب کې بیان شوې دي، د هغه په سر باندې راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_18.mp3', '', 1761754199, 1761754199),
(32072, 'Revelation 22:19', 'Revelation', 22, 19, 'او که څوک د دې پېشګویانو او پیغام څخه کوم څه کم کړي، نو خدای به هغه د ژوندانه د ونې او سپېڅلي ښار نه چې په دې کتاب کې بیان شوي دي، بې‌برخې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_19.mp3', '', 1761754199, 1761754199),
(32073, 'Revelation 22:20', 'Revelation', 22, 20, 'هغه څوک چې د دې ټولو شیانو په هکله شاهدي ورکوي، وایي: «هو، زه زر درځم!» امین، ای څښتنه عیسی، راشه!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation22_verse_20.mp3', '', 1761754199, 1761754199),
