(32089, 'John 1:15', 'John', 1, 15, 'یحیی خلکو ته د هغه په هکله شاهدي ورکړې وه. هغه په لوړ اواز وویل: «دا هغه څوک دی چې ما د هغه په هکله ویلي وو چې زما څخه وروسته به راځي، خو هغه زما څخه ډېر لوی دی، ځکه چې زه لا پیدا شوی نه وم چې هغه موجود ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_15.mp3', '', 1761754199, 1761754199),
(32090, 'John 1:16', 'John', 1, 16, 'هغه د خپلې زیاتې مهربانۍ له مخې مونږ ټولو ته برکت راکړ، مونږ ته یې د یو برکت پسې بل برکت راکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_16.mp3', '', 1761754199, 1761754199),
