(32102, 'John 1:28', 'John', 1, 28, 'دا ټولې پېښې په بیت‌عنیا کې چې د اردن د سیند په بله غاړه باندې پروت دی یعنې په هغه ځای کې چې یحیی خلکو ته د تعمید غسل ورکاوه، وشوې. د خدای له خوا د قربانۍ وری', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_28.mp3', '', 1761754199, 1761754199),
(32103, 'John 1:29', 'John', 1, 29, 'بله ورځ یحیی ولیدل چې عیسی د هغه خواته راروان دی، نو هغه وویل: «ګورئ، دا د خدای له خوا هغه وری دی چې د نړۍ د خلکو ګناهونه لېرې کوي!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_29.mp3', '', 1761754199, 1761754199),
(32104, 'John 1:30', 'John', 1, 30, 'دا هماغه دی چې د هغه په هکله ما ویلي وو چې زما څخه وروسته به یو څوک راځي چې زما څخه ډېر لوی دی، ځکه چې زه لا نه وم پیدا شوی چې هغه موجود ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_30.mp3', '', 1761754199, 1761754199),
(32105, 'John 1:31', 'John', 1, 31, 'ما هغه نه پېژانده چې هغه به څوک وي، خو زه راغلم چې د اوبو په وسیله د تعمید غسل ورکړم د دې دپاره چې هغه د اسراییلو خلکو ته وروپېژنم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_31.mp3', '', 1761754199, 1761754199),
(32106, 'John 1:32', 'John', 1, 32, 'بیا یحیی دا شاهدي ورکړه: «ما روح القدس ولیده چې د کوترې په شکل د اسمان نه رانازل شو او په هغه باندې کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_32.mp3', '', 1761754199, 1761754199),
(32107, 'John 1:33', 'John', 1, 33, 'ما هغه نه پېژانده خو هغه چا چې زه یې راولېږلم چې د اوبو په وسیله د تعمید غسل ورکړم ماته ویلي وو: ‹هرکله چې ته ووینې چې په کوم چا باندې روح القدس نازل شي او په هغه باندې کښېني، نو پوه شه چې دا هماغه سړی دی چې د روح القدس په وسیله به د تعمید غسل ورکوي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_33.mp3', '', 1761754199, 1761754199),
(32108, 'John 1:34', 'John', 1, 34, 'ما ولیدل چې داسې وشول او شاهدي ورکوم چې هغه د خدای زوی دی.» د عیسی مسیح لومړني شاګردان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_34.mp3', '', 1761754199, 1761754199),
(32109, 'John 1:35', 'John', 1, 35, 'په بله ورځ یحیی بیا د خپلو دوه شاګردانو سره ولاړ ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_35.mp3', '', 1761754199, 1761754199),
(32110, 'John 1:36', 'John', 1, 36, 'کله چې هغه ولیدل چې عیسی له هغه ځای څخه تېریږي نو ویې ویل: «ګورئ، دا دی د خدای له خوا د قربانۍ وری!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_36.mp3', '', 1761754199, 1761754199);